using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public static class EnhancementTests
{
 static int checks;static void Check(bool ok,string name){if(!ok)throw new Exception("UPGRADE FAIL: "+name);checks++;Console.WriteLine("UPGRADE PASS: "+name);}
 static bool Near(double a,double b)=>Math.Abs(a-b)<.001;
 static EnhancementDefinition Def(string kind)=>EnhancementCatalog.All.Single(d=>d.Kind==kind);
 static int Slot(EnhancementDefinition d)=>d.Slot=="high"?0:d.Slot=="medium"?2:8;
 static DemoWorld World(string hull="command"){var w=new DemoWorld();w.NewGame(0);w.EnhancementTrial(hull);w.Credits=100000;return w;}
 static void Install(DemoWorld w,string kind,int slot=-1){var d=Def(kind);Check(w.FitEnhancement(d.Id,true,slot<0?Slot(d):slot),"Install "+kind);}
 public static void Run()
 {
  Check(EnhancementCatalog.All.Length==21,"All 21 distinct module families");Check(EnhancementCatalog.Scripts.Length==7,"Seven reusable script modes");
  foreach(var d in EnhancementCatalog.All)
  {
   var w=World(d.Kind=="Fighter"?"carrier":"command");int slot=Slot(d);float stock=w.ItemCount(d.Id,true);Check(ItemCatalog.All.Any(i=>i.Id==d.Id),d.Name+" item database");Check(w.Offers(d.Id,w.SystemId,false).Any(),d.Name+" market stock");Check(w.FitEnhancement(d.Id,true,slot),d.Name+" fits");var s=w.Player.Enhancements[slot];Check(w.ItemCount(d.Id,true)==stock-1,d.Name+" consumes real inventory");Check(w.Player.Stat("cpuLoad")>=d.Cpu&&w.Player.Stat("powerLoad")>=d.Power,d.Name+" shared resources");Check(!w.ToggleEnhancement(slot),d.Name+" cannot activate docked/passive");
   if(d.Active){w.Undock();float cap=w.Player.Cap;Check(w.ToggleEnhancement(slot),d.Name+" starts cycle");Check(Near(cap-w.Player.Cap,d.Capacitor),d.Name+" charges capacitor");Check(s.Active&&Near(s.CycleLeft,d.Cycle),d.Name+" paid cycle");s.Repeat=false;w.UpdateEnhancements(d.Cycle+.01f);Check(!s.Active,d.Name+" finishes single cycle");w.Screen=ViewMode.Station;}
   else Check(s.Effective,d.Name+" online passive effect");
   Check(w.SetEnhancementOnline(slot,false)&&!s.Effective,d.Name+" offline removes effect");Check(w.SetEnhancementOnline(slot,true),d.Name+" re-online");Check(w.UnfitEnhancement(slot)&&w.ItemCount(d.Id,true)==stock,d.Name+" unfit restores stock");
  }
  // Family specificity and multiplicative diminishing damage/cadence.
  var weaponFamilies=new[]{("ProjectileDamage","Artillery"),("LaserDamage","Beam lasers"),("HybridDamage","Railguns"),("EntropicDamage","Entropic"),("ArcDamage","Arc"),("MissileDamage","Missile")};
  foreach(var (kind,family) in weaponFamilies)
  {
   var w=World();Install(w,kind);var a=WeaponCatalog.All.First(d=>family=="Entropic"?d.Kind==WeaponKind.Entropic:family=="Arc"?d.Kind==WeaponKind.Arc:family=="Missile"?d.Kind==WeaponKind.Missile:d.Family==family);
   Check(w.Player.WeaponEnhancement(a,"damage")>1&&w.Player.WeaponEnhancement(a,"cycle")<1,kind+" damage and cadence");var unrelated=WeaponCatalog.All.First(d=>d.Kind==WeaponKind.Smartbomb);Check(Near(w.Player.WeaponEnhancement(unrelated,"damage"),1),kind+" excludes smartbomb");float first=w.Player.WeaponEnhancement(a,"damage");Install(w,kind,9);float second=w.Player.WeaponEnhancement(a,"damage");Check(second>first&&second<first*first,kind+" diminishing stack");Check(w.SetEnhancementOnline(8,false)&&Near(w.Player.WeaponEnhancement(a,"damage"),first),kind+" offline strongest stack recalculated");
  }
  foreach(string kind in new[]{"Tracking","DroneTracking","Sensor","Guidance"})
  {
   var w=World();Install(w,kind);int slot=Slot(Def(kind));var s=w.Player.Enhancements[slot];foreach(var script in EnhancementCatalog.Scripts.Where(p=>EnhancementCatalog.Fits(Def(kind),p)))
   {float old=w.ItemCount(script.Id,true);Check(w.LoadEnhancementScript(slot,script.Id),kind+" loads "+script.Name);Check(w.ItemCount(script.Id,true)==old-1,"Script reserves one real item");w.Undock();w.ToggleEnhancement(slot);Check(s.EffectiveBonuses().All(b=>b.Key.EndsWith("Add")||Near(b.Value,Def(kind).Bonuses[b.Key]*2)),kind+" selected effects doubled");Check(!w.LoadEnhancementScript(slot,""),"Cannot change script mid-cycle");w.ToggleEnhancement(slot);w.UpdateEnhancements(Def(kind).Cycle+.001f);w.Screen=ViewMode.Station;Check(w.LoadEnhancementScript(slot,"")&&w.ItemCount(script.Id,true)==old,"Reusable script returned intact");}
  }
  var sensor=World();Install(sensor,"Sensor",2);Install(sensor,"SensorPassive",8);double baseRange=sensor.Player.Attributes["maxTargetRange"]!.Value;sensor.Undock();sensor.ToggleEnhancement(2);Check(sensor.Player.Stat("maxTargetRange")>baseRange&&sensor.Player.Stat("scanResolution")>sensor.Player.Attributes["scanResolution"],"Sensors alter real lock stats");Check(sensor.Player.Stat("scanMagnetometricStrength")>sensor.Player.Attributes["scanMagnetometricStrength"],"ECCM strength alters real sensor defense");
  var tracking=World();Install(tracking,"Tracking",2);Install(tracking,"TrackingPassive",8);tracking.Undock();tracking.ToggleEnhancement(2);float local=tracking.Player.SupportFactor("tracking");tracking.Player.SupportEffects.Add(new(){Key="remote",Left=20,Bonuses=new(){{"tracking",.1f}}});Check(tracking.Player.SupportFactor("tracking")>local&&tracking.Player.SupportFactor("tracking")<local*1.1f,"Remote and local tracking share stacking group");
  var missile=World();Install(missile,"GuidancePassive");Check(missile.Player.Stat("missileVelocity")>missile.Player.Attributes["missileVelocity"]&&missile.Player.Stat("explosionRadius")<missile.Player.Attributes["explosionRadius"],"Guidance changes live missile stats");var launcher=WeaponCatalog.All.First(d=>d.Kind==WeaponKind.Missile&&d.Size==1);Check(missile.WeaponReach(WeaponState.Create(launcher.Id))>launcher.Velocity*launcher.FlightTime,"Guidance increases firing reach");
  // Real launch paths capture amplified volley, velocity, flight time and application.
  var live=World();Install(live,"MissileDamage");Install(live,"GuidancePassive",9);Check(live.FitWeapon(launcher.Id,true,0),"Prepare guided launcher");live.LoadWeapon(0,ChargeCatalog.For(launcher)[0].Id);live.EnterWeaponRange();live.SelectedId=live.LockedId="range_0";live.ToggleWeapon(0);live.Update(.05f);var ord=live.MissilesInFlight.First(m=>m.Owner=="player"&&!m.Bomb);Check(ord.Packet.Total>launcher.Damage*(live.Player.Weapons[0].Charge?.DamageMultiplier??1),"Actual missile packet amplified");Check(ord.Speed>launcher.Velocity&&ord.ExplosionRadius<launcher.ExplosionRadius&&ord.ExplosionVelocity>launcher.ExplosionVelocity,"Actual missile speed and application enhanced");Check(live.Player.Weapons[0].Cooldown<launcher.Cycle,"Actual launcher cooldown reduced");
  var scope=World();Install(scope,"TrackingPassive");var chain=WeaponCatalog.All.First(d=>d.Kind==WeaponKind.Arc);Check(Near(scope.WeaponReach(WeaponState.Create(chain.Id)),chain.Optimal+chain.Falloff*3),"Ordinary tracking support excludes chain projector range");
  var ecm=World();Install(ecm,"Ecm");Check(ecm.Player.EnhancementFactor("ecmStrength")>1&&ecm.Player.EnhancementFactor("ecmOptimal")>1,"Targeted jammer strength and optimal support");Check(Near(ecm.Player.SupportFactor("ewar"),1),"Mirage amplifier does not enhance dampeners or bursts");
  var drone=World();Install(drone,"DroneRange");double range=drone.Player.Stat("droneControlDistance");Check(range>48000,"Drone control range expanded");Check(drone.UnfitEnhancement(0)&&Near(drone.Player.Stat("droneControlDistance"),48000),"Drone link additive range removed");Install(drone,"DroneDamage");Install(drone,"DroneSpeed",2);Install(drone,"DroneTrackingPassive",9);var dd=DroneCatalog.All.First(d=>d.Kind=="Combat"||!d.Fighter&&d.Packet.Total>0);var du=DroneUnit.Create(dd.Id);drone.Player.Drones.Add(du);var effective=drone.EffectiveDrone(du);Check(effective.Packet.Total>dd.Packet.Total&&effective.Speed>dd.Speed&&effective.Tracking>dd.Tracking&&effective.Optimal>dd.Optimal,"Drone actual model receives all support");Check(drone.Player.BayDroneDps>dd.Packet.Total/dd.Cycle,"Drone fitting DPS includes support");Check(Near(effective.Yield,dd.Yield)&&Near(effective.Repair,dd.Repair),"Combat support does not inflate harvesting or repairs");
  var fighter=World("supercarrier");Install(fighter,"Fighter");Install(fighter,"DroneDamage");Install(fighter,"DroneTrackingPassive",9);Install(fighter,"DroneSpeed",2);var fd=DroneCatalog.All.First(d=>d.Kind=="AttackFighter");var fu=DroneUnit.Create(fd.Id,fd.SquadronSize,0);fighter.Player.Drones.Add(fu);fighter.RefreshEnhancedFighters();var ef=fighter.EffectiveDrone(fu);Check(ef.Cycle<fd.Cycle&&ef.Speed>fd.Speed&&ef.Shield>fd.Shield&&ef.ShieldRecharge<fd.ShieldRecharge,"FSU four actual fighter attributes");Check(ef.AttackExplosionRadius<fd.AttackExplosionRadius&&ef.AttackExplosionVelocity>fd.AttackExplosionVelocity,"Omnidirectional fighter missile application");Check(fu.Shield>fd.Shield&&fu.ReserveHealth.All(h=>h.Shield>fd.Shield),"All squadron members receive shield capacity");fu.Shield=ef.Shield*.4f;fighter.SetEnhancementOnline(0,false);Check(Near(fu.Shield,fd.Shield*.4f),"Removing fighter support preserves damaged shield fraction");var plain=DroneUnit.Create(dd.Id);Check(Near(fighter.EffectiveDrone(plain).Shield,dd.Shield),"FSU excludes normal drone shields");Check(World().EnhancementFitError(Def("Fighter"),0).Length>0,"FSU hull role restriction");
  // Multiple locks, acquisition scaling, automatic aggressor acquisition and silent reveal.
  var locks=World();Install(locks,"Auto");Check(locks.TargetCapacity==6,"Auto extra locks work while online and inactive");Install(locks,"SensorPassive");Check(locks.TargetCapacity==7,"Signal amplifier extra target slot adds");locks.EnterWeaponRange();locks.ClearEnhancedLocks();locks.LockedId="";foreach(var t in locks.Targets)t.LockId="player";Check(locks.ToggleEnhancement(0),"Auto acquisition activation");locks.UpdateEnhancements(Def("Auto").Cycle+.001f);Check(locks.Acquisitions.Count+locks.RetainedLocks.Count==5,"Auto acquires five hostile aggressors and excludes friendly");locks.UpdateEnhancements(30);Check(locks.RetainedLocks.Count==5,"Auto retains multiple completed locks");locks.UnlockEnhancedTarget("range_0");Check(locks.RetainedLocks.Count==4,"Individual target unlock");locks.Targets.First(t=>t.Id=="range_1").Position=new(1000000,0,0);locks.UpdateEnhancements(.01f);Check(!locks.RetainedLocks.Any(l=>l.Id=="range_1"),"Out-of-range retained lock removed");
  var quiet=World();Install(quiet,"Passive",2);quiet.EnterWeaponRange();quiet.LockedId="";quiet.SelectedId="range_0";Check(quiet.ToggleEnhancement(2),"Silent array arms");quiet.LockTarget();Check(quiet.Acquisitions.Count==1&&quiet.Acquisitions[0].Silent,"Passive targeter silently begins selected ship lock");quiet.UpdateEnhancements(30);Check(quiet.RetainedLocks.Single().Silent,"Silent lock remains hidden after acquisition");Check(!quiet.Targets.First(t=>t.Id=="range_0").PlayerLockNotified,"Silent acquisition does not notify recipient");quiet.RevealEnhancedLock("range_0");Check(!quiet.RetainedLocks.Single().Silent,"Attack reveals silent lock");Check(quiet.Targets.First(t=>t.Id=="range_0").PlayerLockNotified,"Offensive action notifies recipient");var target=quiet.Targets.First();float seconds=quiet.AcquisitionSeconds(target);quiet.Player.SetStat("scanResolution",quiet.Player.Stat("scanResolution")*2);Check(quiet.AcquisitionSeconds(target)<seconds,"Actual acquisition speed uses scan resolution");

  var transfers=World("supercarrier");Install(transfers,"Fighter");float sf=transfers.Player.EnhancementFactor("fighterShield");Check(transfers.LoadDrone(fd.Id,true,2,0),"Load boosted fighter pair");var pair=transfers.Player.Drones.First(u=>u.Location=="Bay");pair.Shield=fd.Shield*sf*.3f;Check(Near(pair.ReserveHealth[0].Shield,fd.Shield*sf),"New fighter member shield boosted exactly once");Check(transfers.LoadDrone(fd.Id,true,1,0)&&Near(pair.Shield,fd.Shield*sf*.3f)&&pair.ReserveHealth.All(h=>Near(h.Shield,fd.Shield*sf)),"Loading into existing squadron preserves damaged member");Check(transfers.UnloadDrone(pair.Id)&&Near(pair.Shield,fd.Shield*.3f),"Hangar unload removes ship bonus without healing");Check(transfers.LoadDrone(fd.Id,true,3,0),"Reload stored damaged squadron");pair=transfers.Player.Drones.First(u=>u.Location=="Bay");Check(Near(pair.Shield,fd.Shield*sf*.3f),"Reload does not multiply bonus twice");Check(transfers.StoreFighterReserve(fd.Id,2),"Load boosted reserve fighters");var reserve=transfers.Player.Drones.First(u=>u.Location=="Reserve");reserve.Shield=fd.Shield*sf*.6f;Check(transfers.ReplenishFighter(reserve.Id,0)&&Near(pair.Shield,fd.Shield*sf*.3f)&&pair.ReserveHealth.Any(h=>Near(h.Shield,fd.Shield*sf*.6f)),"Reserve transfer preserves individual shield damage");transfers.EnterDroneRange();Check(transfers.LaunchDrone(pair.Id)&&Near(transfers.Targets.First(t=>t.Id==pair.Id).Profile!.MaxShield,fd.Shield*sf),"Live fighter body uses boosted shield maximum");Check(transfers.Player.ActiveDroneDps>fd.Packet.Total*pair.Count/fd.Cycle,"Active fighter DPS reflects both cadence and amplification");
  var onlineBudget=World();Install(onlineBudget,"Tracking",2);double cpu=onlineBudget.Player.Stat("cpuLoad");onlineBudget.SetEnhancementOnline(2,false);Check(Near(onlineBudget.Player.Stat("cpuLoad"),cpu-Def("Tracking").Cpu),"Offline frees actual CPU");onlineBudget.Player.SetStat("cpuOutput",onlineBudget.Player.Stat("cpuLoad"));Check(!onlineBudget.SetEnhancementOnline(2,true),"Re-online enforces CPU budget");
  // Cycle payment, overload burnout, script stock, equipment condition and save compatibility.
  var heat=World();Install(heat,"Sensor",2);heat.Undock();var hs=heat.Player.Enhancements[2];hs.Overheat=true;hs.Damage=.99f;Check(heat.ToggleEnhancement(2)&&hs.Burnt&&!hs.Effective,"Overload burns module and removes effect");heat.Screen=ViewMode.Station;Check(heat.UnfitEnhancement(2)&&heat.HasDamagedEnhancementStock(Def("Sensor").Id,true),"Damaged condition retained in stock");Check(heat.FitEnhancement(Def("Sensor").Id,true,2)&&heat.Player.Enhancements[2].Burnt,"Damaged module cannot reset through refit");Check(heat.RepairEnhancement(2)&&!heat.Player.Enhancements[2].Burnt,"Paid station repair restores module");
  var poor=World();Install(poor,"Tracking",2);poor.Undock();poor.Player.Cap=0;Check(!poor.ToggleEnhancement(2),"Zero capacitor blocks activation");poor.SetEnhancementOnline(2,false);Check(!poor.SetEnhancementOnline(2,true),"In-space online capacitor requirement enforced");
  var budgets=World("frigate");budgets.Player.SetStat("cpuOutput",10000);budgets.Player.SetStat("powerOutput",10000);Install(budgets,"Tracking",2);Install(budgets,"Tracking",3);Install(budgets,"Tracking",4);Check(budgets.EnhancementFitError(Def("Tracking"),5).Length>0,"Shared medium slot cap enforced");Check(budgets.EwarFitError(EwarCatalog.All.First(d=>d.Kind==EwarKind.Web),1).Length>0,"EWAR reverse slot cap sees upgrades");Check(budgets.DefenseFitError(DefenseCatalog.All.First(d=>d.Kind=="ShieldBoost"&&d.Size==1),1).Length>0,"Defense reverse slot cap sees upgrades");
  string temp=Path.Combine(Path.GetTempPath(),"ss-upgrade-"+Guid.NewGuid());string? oldEnv=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");try{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",temp);quiet.Player.Enhancements[2].Damage=.3f;quiet.BeginAcquisition("range_2",true);quiet.Save();var load=new DemoWorld();Check(load.Load(),"Cumulative upgrade save loads");Check(load.Player.Enhancements[2].ModuleId==Def("Passive").Id&&Near(load.Player.Enhancements[2].Damage,.3f),"Fitting and condition persist");Check(load.RetainedLocks.Count==quiet.RetainedLocks.Count&&load.Acquisitions.Any(a=>a.Id=="range_2"&&a.Silent),"Retained locks and silent pending acquisitions persist");load.EnterGrid("belt");Check(load.RetainedLocks.Count==0&&load.Acquisitions.Count==0,"Transit clears lock state");}finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",oldEnv);if(Directory.Exists(temp))Directory.Delete(temp,true);}
  Console.WriteLine($"{checks} damage, targeting and flight support checks passed.");
 }
}
